def feats(src):
    f = {}
    try:
        tree = ast.parse(src)
    except (SyntaxError, ValueError):
        return None
    mods = set(); calls = set(); attrs = set(); names = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            mods |= {a.name.split('.')[0] for a in n.names}
        elif isinstance(n, ast.ImportFrom) and n.module:
            mods.add(n.module.split('.')[0])
        elif isinstance(n, ast.Call):
            if isinstance(n.func, ast.Name): calls.add(n.func.id)
            elif isinstance(n.func, ast.Attribute): attrs.add(n.func.attr)
        elif isinstance(n, ast.Attribute):
            if isinstance(n.value, ast.Name): names.add(n.value.id + '.' + n.attr)
    f['mods'] = mods
    f['net'] = bool(mods & NET)
    f['proc'] = bool(mods & PROC) or 'os.system' in names or 'os.popen' in names
    f['env'] = 'os.environ' in names or 'getenv' in attrs or 'os.getenv' in names
    f['fs'] = ('open' in calls) or bool(mods & FSMOD) or bool(attrs & FS_CALL_ATTR) or any(x.startswith('os.path') for x in names)
    f['stdin'] = 'sys.stdin' in names or 'input' in calls
    f['argv'] = 'sys.argv' in names or 'argparse' in mods
    f['json_stdin'] = f['stdin'] and 'json' in mods
    f['time'] = bool(mods & {'time','datetime'}) 
    f['random'] = 'random' in mods or 'uuid' in mods or 'secrets' in mods
    f['project_import'] = bool(mods & {'lypning','training','round02','data_loop'}) or any(m.startswith(('lypning','train')) for m in mods)
    third = mods - set(sys.stdlib_module_names) - {'lypning','training'}
    f['thirdparty'] = bool(third) and not f['project_import']
    f['third_mods'] = third
    f['mutation'] = corpus_safety.external_mutation(tree)
    f['stmts'] = len(tree.body)
    f['defs'] = sum(isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.AsyncFunctionDef, ast.Lambda)) for n in ast.walk(tree))
    f['loops'] = sum(isinstance(n, (ast.For, ast.While, ast.comprehension)) for n in ast.walk(tree))
    f['nodes'] = sum(1 for _ in ast.walk(tree))
    return f
