        residual += bool(PAT.search(prog))
        items.append({'pool': label, 'model': r['model'], 'sha': r['sha'], 'program': prog})
    stats[label] = {'source': src, 'available_tierA_clean': len(cand), 'excluded_contaminated': excluded,
