"""Parse-only A/B: every corpus program through the base and the fixed binary,
with `raise SystemExit(0)` in front so nothing runs. Reports every program whose
exit code or stderr changed."""
import json, subprocess, sys, glob
from concurrent.futures import ThreadPoolExecutor
A = '/tmp/lyp-home-engine-base/bin/'
B = '/tmp/lyp-home-engine/bin/'
root = sys.argv[1]
progs = {}
for f in [root + '/src/lypning/assets/corpus/corpus.jsonl'] + glob.glob(root + '/tests/corpus/sightings/*.jsonl'):
    for l in open(f):
        if l.strip():
            d = json.loads(l)
            progs.setdefault(d.get('id') or d.get('key'), d['program'])
print('programs', len(progs))

def one(item):
    pid, src = item
    out = []
    for eng in ('lypning', 'lypning-l'):
        ra = subprocess.run([A + eng, '-c', 'raise SystemExit(0)\n' + src], capture_output=True, text=True, timeout=20, stdin=subprocess.DEVNULL)
        rb = subprocess.run([B + eng, '-c', 'raise SystemExit(0)\n' + src], capture_output=True, text=True, timeout=20, stdin=subprocess.DEVNULL)
        if (ra.returncode, ra.stderr) != (rb.returncode, rb.stderr):
            out.append((pid, eng, ra.returncode, ra.stderr.strip()[-120:], rb.returncode, rb.stderr.strip()[-120:]))
    return out

with ThreadPoolExecutor(8) as tp:
    for res in tp.map(one, progs.items()):
        for r in res:
            print(r)

