"""Parse-only sweep: every 'program'-like string field in JSONL files under the
given roots; report programs CPython compiles but lypning-l rejects with a
SyntaxError. Execution is prevented by prefixing `raise SystemExit(0)`."""
import json, os, subprocess, sys, collections

BIN = '/tmp/lyp-home-engine/bin/lypning-l'
roots = sys.argv[1:]
seen = set()
progs = []

def walk(o):
    if isinstance(o, dict):
        for k, v in o.items():
            if isinstance(v, str) and k in ('program', 'reference', 'completion', 'code', 'solution', 'source', 'text', 'response'):
                yield v
            else:
                yield from walk(v)
    elif isinstance(o, list):
        for v in o:
            yield from walk(v)

for root in roots:
    for dp, dn, fn in os.walk(root):
        dn[:] = [d for d in dn if d not in ('target', '.git', 'node_modules')]
        for f in fn:
            if not (f.endswith('.jsonl') or f.endswith('.json')):
                continue
            p = os.path.join(dp, f)
            try:
                if os.path.getsize(p) > 200_000_000:
                    continue
                with open(p, encoding='utf-8', errors='replace') as fh:
                    if f.endswith('.json'):
                        docs = [json.load(fh)]
                    else:
                        docs = (json.loads(l) for l in fh if l.strip())
                    for d in docs:
                        for s in walk(d):
                            if s not in seen:
                                seen.add(s)
                                progs.append(s)
            except Exception:
                continue

print('candidates', len(progs), file=sys.stderr)
hits = collections.Counter()
examples = {}
for s in progs:
    try:
        compile(s, '<p>', 'exec')
    except BaseException:
        continue
    try:
        r = subprocess.run([BIN, '-c', 'raise SystemExit(0)\n' + s], capture_output=True, text=True, timeout=10, stdin=subprocess.DEVNULL)
    except Exception:
        continue
    if r.returncode == 1 and 'SyntaxError' in r.stderr:
        msg = r.stderr.strip().splitlines()[-1]
        hits[msg] += 1
        examples.setdefault(msg, s)
for m, n in hits.most_common():
    print(n, m)
json.dump(examples, open(os.path.join(os.path.dirname(__file__), 'sweep_examples.json'), 'w'), indent=1)

