import ast, re, textwrap
from pathlib import Path
HEREDOC = re.compile(r"^([^\n]*python3?\b[^\n]*<<-?\s*'?(\w+)'?[^\n]*)\n(.*?)\n\s*\2\s*$", re.M | re.S)
DASHC = re.compile(r"python3?\s+-c\s+'([^']*)'")
def bodies(text):
    for m in HEREDOC.finditer(text):
        yield m.group(1)[:50], textwrap.dedent(m.group(3))
    for m in DASHC.finditer(text):
        yield "-c", m.group(1)
for p in sorted(Path("training/hf").glob("*.sh")) + sorted(Path(".github/workflows").glob("*.yml")):
    t = p.read_text()
    n = 0
    for head, b in bodies(t):
        n += 1
        try:
            ast.parse(b)
        except SyntaxError as e:
            print("NOPARSE", p, head, e)
    print(p, n)

